#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> highlights;
    for (int i = 1; i <= N; ++i) {
        int A;
        cin >> A;
        if (A == 1) highlights.push_back(i);
    }

    long long answer = 0;
    for (int i = 0; i < static_cast<int>(highlights.size()); ++i) {
        int previous = (i == 0 ? 0 : highlights[i - 1]);
        int next = (i + 1 == static_cast<int>(highlights.size())
                        ? N + 1
                        : highlights[i + 1]);
        answer += 1LL * (highlights[i] - previous) * (next - highlights[i]);
    }

    cout << answer << '\n';
    return 0;
}
